Gfx night_snow_alpha[] = {
    gsDPSetPrimColor(0, 0, 255, 255, 255, 215),
    gsSPEndDisplayList(),
};

// An adding blend: what is drawn brightens what is behind it, by its own alpha, and hides nothing;
// the depth test keeps it behind the land. (The gbi's G_RM_ADD blends by the fog's alpha, not the
// pixel's, and added nothing here.)
#define RM_GLOW(clk) (Z_CMP | IM_RD | CVG_DST_FULL | ZMODE_XLU | FORCE_BL | GBL_c##clk(G_BL_CLR_IN, G_BL_A_IN, G_BL_CLR_MEM, G_BL_1))
Gfx night_glow_begin[] = {
    gsSPDisplayList(night_rain_begin),
    gsDPSetRenderMode(RM_GLOW(1), RM_GLOW(2)),
    gsDPSetPrimColor(0, 0, 255, 255, 255, 255),
    gsSPEndDisplayList(),
};

